 public void onCreate(Bundle b){super.onCreate(b);p=getSharedPreferences("parent",0);try{tw.rex.link.SettingsMigration.upgrade(p);}catch(RuntimeException error){recordError("讀取舊設定",error);}migrateContent();ready=true;h.post(refresh);}
