 void migrateContent(){Map<String,Object> changes=ParentContent.migration(p.getAll());if(changes.isEmpty())return;android.content.SharedPreferences.Editor editor=p.edit();for(Map.Entry<String,Object> item:changes.entrySet()){if(item.getValue() instanceof Boolean)editor.putBoolean(item.getKey(),(Boolean)item.getValue());else editor.putString(item.getKey(),(String)item.getValue());}editor.apply();}
