 void base(String title){FrameLayout frame=new FrameLayout(this);frame.setBackground(Skin.background(this,false));ScrollView sc=new ScrollView(this);sc.setFillViewport(false);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(16),dp(16),dp(16),dp(22));Skin.card(root);sc.addView(root);FrameLayout.LayoutParams spacing=new FrameLayout.LayoutParams(-1,-1);spacing.setMargins(dp(14),dp(28),dp(14),dp(160));frame.addView(sc,spacing);setContentView(frame);label(title,26);TextView author=label("作者：雷允澤 · v1.3.12",13);author.setPadding(dp(3),dp(1),dp(3),dp(8));Button skins=Skin.button(this,"手機皮膚 · "+Skin.name(this),2);skins.setTextSize(15);root.addView(skins,new LinearLayout.LayoutParams(-1,dp(46)));skins.setOnClickListener(v->Skin.picker(this,Skin.id(this),id->{Skin.set(this,id);Skin.restyle(frame);skins.setText("手機皮膚 · "+Skin.name(this));}));}
