 EditText input(String hint,String value,boolean number){EditText e=new EditText(this);e.setHint(hint);e.setText(value);e.setTextSize(18);e.setTextColor(Skin.ink(this));e.setHintTextColor(0xff6b7180);e.setBackground(Skin.panel(this));e.setPadding(dp(12),dp(11),dp(12),dp(11));if(number)e.setInputType(InputType.TYPE_CLASS_NUMBER);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(4),0,dp(8));root.addView(e,lp);return e;}
 void msg(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 void login(boolean force,Runnable done){page="login";boolean create=pString("pinHash","").isEmpty();base(create?"設定家長密碼":"家長驗證");label(create?"請設定六位數家長密碼。每次重新進入家長端都需要輸入。":"輸入六位數家長密碼",17);EditText pin=input("六位數密碼","",true);pin.setInputType(18);EditText confirm=create?input("再次輸入密碼","",true):null;if(confirm!=null)confirm.setInputType(18);button(create?"設定並開始":"解鎖家長端",()->{try{long wait=pLong("blockedUntil",0)-System.currentTimeMillis();if(wait>0){msg("請等 "+(wait/1000+1)+" 秒後重試");return;}String code=pin.getText().toString();if(!code.matches("[0-9]{6}")){msg("請輸入六位數字");return;}if(create&&!code.equals(confirm.getText().toString())){msg("兩次密碼不一致");return;}String salt=create?Crypto.b64(Crypto.random(16)):pString("pinSalt","");String hash=Crypto.pinHash(code,salt);if(!create&&!hash.equals(pString("pinHash",""))){int failures=pInt("failures",0)+1;p.edit().putInt("failures",failures).putLong("blockedUntil",failures>=5?System.currentTimeMillis()+30000:0).apply();msg("密碼錯誤"+(failures>=5?"，暫停 30 秒":""));return;}if(create)p.edit().putString("pinHash",hash).putString("pinSalt",salt).putString("recovery",UUID.randomUUID().toString().replace("-","").substring(0,20).toUpperCase()).commit();p.edit().putInt("failures",0).putLong("blockedUntil",0).apply();authed=true;Intent i=new Intent(this,ParentService.class);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=0)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},11);if(done!=null)done.run();else home();if(create)recovery();}catch(Exception e){msg("驗證失敗："+e.getClass().getSimpleName());}});}
 void recovery(){new AlertDialog.Builder(this).setTitle("請保存家長復原碼").setMessage(pString("recovery","")+"\n\n手機遺失或斷網時，可在電視黑屏上的「家長緊急復原」輸入此碼。請勿讓孩子取得。").setPositiveButton("已保存",null).show();}
 void home(){page="home";selected="";deviceButtons.clear();base("邊看邊學・家長端");LinearLayout stats=new LinearLayout(this);String[] counts={"331題","100智力題","4套皮膚"};for(int i=0;i<3;i++){LinearLayout cell=new LinearLayout(this);cell.setOrientation(1);cell.setGravity(Gravity.CENTER);cell.setPadding(dp(4),dp(6),dp(4),dp(6));Skin.card(cell);cell.addView(Skin.icon(this,i),new LinearLayout.LayoutParams(-1,dp(50)));TextView value=new TextView(this);value.setText(counts[i]);value.setTextSize(14);value.setGravity(Gravity.CENTER);value.setTypeface(null,android.graphics.Typeface.BOLD);Skin.text(value);cell.addView(value);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,-2,1);cp.setMargins(dp(3),dp(8),dp(3),dp(8));stats.addView(cell,cp);}root.addView(stats);label("手機與電視連接同一個 Wi-Fi。保持連線服務開啟，電視端便會自動搜尋。",17);button("首頁鍵保護設定／電視裝置資訊",()->openHomeProtection());button("問題回報／錯誤紀錄",()->showDiagnostics());status=label(ParentService.info,15);deviceList=new LinearLayout(this);deviceList.setOrientation(1);root.addView(deviceList);button("重新搜尋／啟動連線服務",()->{Intent service=new Intent(this,ParentService.class);if(Build.VERSION.SDK_INT>=26)startForegroundService(service);else startService(service);msg("已啟動自動搜尋，請開啟電視端，約數秒後顯示電視卡片");});button("查看手動連線 IP 與埠",()->addresses());button("管理自訂題庫",()->customList());button("家長端一鍵更新 · v1.3.12",()->tw.rex.link.UpdateClient.check(this,false));button("查看家長復原碼",()->recovery());button("鎖定家長端",()->{authed=false;login(false,null);});button("停止手機連線服務",()->{stopService(new Intent(this,ParentService.class));msg("已停止；電視已設定的計時及黑屏不會解除");});label("新手機連線：電視按「自動搜尋家長手機」，選取本手機；點手機上的電視卡片確認連線，再於電視允許。無須輸入配對碼。",15);renderDevices();}
 void renderDevices(){if(deviceList==null||!page.equals("home"))return;status.setText(ParentService.info);if(ParentService.devices.isEmpty()){if(deviceList.getChildCount()==0){TextView t=new TextView(this);Skin.text(t);t.setText("正在等待電視搜尋……\n請先開啟電視端。");t.setTextSize(18);deviceList.addView(t);}return;}if(deviceButtons.isEmpty())deviceList.removeAllViews();for(ParentService.Device d:ParentService.devices.values()){Button b=deviceButtons.get(d.id);if(b==null){b=Skin.button(this,"",0);b.setTextSize(17);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(5),0,dp(5));deviceList.addView(b,lp);deviceButtons.put(d.id,b);final String deviceId=d.id;b.setOnClickListener(v->{ParentService.Device current=ParentService.devices.get(deviceId);if(current==null){msg("電視暫時離線，請稍後重試");return;}if(current.paired){selected=deviceId;controls();}else pair(current);});}boolean online=System.currentTimeMillis()-d.seen<8000;b.setText(d.name+" · "+(d.paired?(online?"已連線":"離線"):(!d.invite.isEmpty()&&System.currentTimeMillis()<d.inviteUntil?"電視邀請連線 · 點此確認":"等待電視選擇此手機"))+"\n點此開啟電視控制  ›");}}
 void openHomeProtection(){ArrayList<ParentService.Device> paired=new ArrayList<ParentService.Device>();for(ParentService.Device d:ParentService.devices.values())if(d.paired)paired.add(d);if(paired.size()==0){new AlertDialog.Builder(this).setTitle("首頁鍵保護設定").setMessage("請先連接並配對電視。此功能需要電視的裝置擁有者權限，上層顯示授權不能取代它。").setPositiveButton("知道了",null).show();return;}if(paired.size()==1){selected=paired.get(0).id;protectionHelp();return;}String[] names=new String[paired.size()];for(int i=0;i<names.length;i++)names[i]=paired.get(i).name;new AlertDialog.Builder(this).setTitle("選擇電視").setItems(names,(dialog,index)->{selected=paired.get(index).id;protectionHelp();}).show();}
 String fingerprint(String pub){try{return Crypto.digest(pub).substring(0,12);}catch(Exception e){return "無法取得";}}
 void pair(ParentService.Device d){if(!d.invite.isEmpty()&&System.currentTimeMillis()<d.inviteUntil){new AlertDialog.Builder(this).setTitle("連線「"+d.name+"」？").setMessage("電視已選擇此手機。確認後，請在電視按「允許」完成配對。\n電視識別碼："+fingerprint(d.pub)).setPositiveButton("確認連線",(dialog,w)->{try{if(ParentService.instance==null)throw new Exception("請重新啟動連線服務");ParentService.instance.acceptInvite(d.id,pString("recovery",""));msg("已確認，請在電視按允許");}catch(Exception e){msg(e.getMessage());}}).setNegativeButton("取消",null).show();return;}EditText code=new EditText(this);code.setInputType(2);code.setHint("電視上的六位數配對碼（舊版備用）");new AlertDialog.Builder(this).setTitle("配對「"+d.name+"」").setMessage("請先比對電視識別碼："+fingerprint(d.pub)+"\n一致後再輸入電視上的六位數配對碼（舊版備用）。").setView(code).setPositiveButton("送出配對",(dialog,w)->{try{if(ParentService.instance==null)throw new Exception("請重新開啟家長端");ParentService.instance.pair(d.id,code.getText().toString(),pString("recovery",""));msg("已送出。請到電視確認配對；錯碼或逾時需重新配對。");}catch(Exception e){msg(e.getMessage());}}).setNegativeButton("取消",null).show();}
 final class Picker extends Button {final String[] options;int position;Picker(String[] values,int value){super(ParentActivity.this);options=values.length==0?new String[]{"尚未取得資料"}:values;Skin.styleButton(this,2);setTextSize(17);setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);setSelection(value);setOnClickListener(v->new AlertDialog.Builder(ParentActivity.this).setTitle("請選擇").setSingleChoiceItems(options,position,(dialog,index)->{setSelection(index);dialog.dismiss();}).setNegativeButton("取消",null).show());}int getSelectedItemPosition(){return position;}void setSelection(int value){position=ParentForm.selection(value,options.length);setText(options[position]+"  ▾");}}
 Picker spinner(String[] opts,int value){Picker picker=new Picker(opts,value);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(4),0,dp(8));root.addView(picker,lp);return picker;}
 void controls(){page="controls";try{base("電視控制");button("返回設備清單",()->home());button("新增家長手機（開放配對5分鐘）",()->send("add_parent",new JSONObject()));label("可由多位已配對家長控制同一台電視；指令依電視收到順序執行，後收到的設定生效。",15);button("首頁鍵保護設定／電視裝置資訊",()->protectionHelp());button("家長解鎖＋取消倒數",()->login(true,()->{controls();send("unlock",new JSONObject());}));button("設定這台電視的皮膚",()->{ParentService.Device tv=ParentService.devices.get(selected);String current=tv!=null&&tv.status!=null?tv.status.optString("skin","ocean"):"ocean";Skin.picker(this,current,id->{try{send("skin",new JSONObject().put("id",id));}catch(Exception e){msg("無法切換電視皮膚");}});});status=label("讀取中",16);button("電視首頁背景音樂設定",()->{ParentService.Device device=ParentService.devices.get(selected);boolean enabled=device!=null&&device.status!=null?device.status.optBoolean("homeMusic",true):true;new AlertDialog.Builder(this).setTitle("電視首頁背景音樂").setSingleChoiceItems(new String[]{"開啟","關閉"},enabled?0:1,(d,w)->{try{send("home_music",new JSONObject().put("enabled",w==0));d.dismiss();}catch(Exception e){msg("無法傳送設定");}}).setNegativeButton("取消",null).show();});safeSection("出題內容",()->studyControls());safeSection("觀看時間",()->watchControls());safeSection("使用時間與兒童鎖",()->timeControls());updateStatus();}catch(RuntimeException|LinkageError|OutOfMemoryError error){recordError("開啟電視控制",error);base("電視控制暫時無法開啟");label("連線資料仍保留。請先使用下方的保護設定，或查看錯誤紀錄。",17);button("新增家長手機（開放配對5分鐘）",()->send("add_parent",new JSONObject()));label("可由多位已配對家長控制同一台電視；指令依電視收到順序執行，後收到的設定生效。",15);button("首頁鍵保護設定／電視裝置資訊",()->protectionHelp());button("查看錯誤紀錄",()->showDiagnostics());button("返回設備清單",()->home());}}
